    'साइटको ठेगानाको बायाँपट्टिको आइकनमा क्लिक गर्नुहोस्, माइक्रोफोन खोल्नुहोस्, र Syden आफैँ जोडिन्छ।',
  'Clique para escolher quais aparecem no seu perfil (até {limite}).': 'तपाईंको प्रोफाइलमा कुन-कुन देखिने छान्न क्लिक गर्नुहोस् ({limite} सम्म)।',
  'Cobre': 'तामा',
