    'कोठाका जोकोहीले पठाउन सक्ने कन्फेटी, आतसबाजी र मुटुहरू। कलको बेला कम्प्युटर अड्कियो भने बन्द गर्नुहोस् — बन्द हुँदा तपाईं न देख्नुहुन्छ न पठाउनुहुन्छ।',
