  'É o nome que todos veem no Syden. Para entrar e nas menções com @, continua valendo o nome da conta.': 'Syden मा सबैले यही नाम देख्छन्। लग इन र @ ले उल्लेख गर्न खाताको नाम नै चल्छ।',
