  'Descartar': 'फाल्नुहोस्',
  'Desconecta o Syden em todos os outros computadores e celulares. Você continua conectado aqui.':
    'अरू सबै कम्प्युटर र मोबाइलमा Syden बाट निकाल्छ। यहाँ भने तपाईं जोडिएकै रहनुहुन्छ।',
  'Desconectando…': 'विच्छेद हुँदै…',
  'Desconectar': 'विच्छेद गर्नुहोस्',
  'Descrição': 'विवरण',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.':
    'बन्द हुँदा, कोठामा भएकाहरूको स्ट्रिम निम्तोजस्तै देखिन्छ र तपाईंले हेर्नुहोस् थिचेपछि मात्र डाउनलोड हुन थाल्छ। यसले इन्टरनेट र प्रोसेसर जोगाउँछ — खासगरी भरिएको कोठामा।',
  'Desligar câmera': 'क्यामेरा बन्द गर्नुहोस्',
  'Deste servidor': 'यो सर्भरबाट',
