  'Digite sua senha para confirmar': 'पुष्टि गर्न आफ्नो पासवर्ड लेख्नुहोस्',
  'Disponível': 'अनलाइन',
  'Do laranja ao vermelho, como carvão aceso.': 'बलिरहेको कोइलाझैँ, सुन्तलादेखि रातोसम्म।',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'दुई इमोजीको नाम एउटै छ: हरेकलाई आफ्नै नाम चाहिन्छ।',
  'Dono': 'मालिक',
  'Dono da comunidade': 'समुदायका मालिक',
  'Dourado com brilho que passa devagar.': 'बिस्तारै सर्ने चमकसहितको सुनौलो।',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.':
    'कलको बेला यो बटनले यी ध्वनिहरू कोठाका सबैलाई बजाउँछ। तयारी प्याक इन्स्टल गर्नुहोस् वा आफ्नै पठाउनुहोस्; मनपर्नेहरू प्यानलको अगाडि रहन्छन्।',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'समुदायमा पस्दा मान्छेले एक पटक मात्र देख्ने पहिलो कुरा यही हो। यो नभए सिधै च्यानल सूचीमा पुगिन्छ।',
  'É assim que os outros veem você na lista e nas conversas.': 'सूची र कुराकानीमा अरूले तपाईंलाई यसरी देख्छन्।',
  'é o que você está enviando': 'तपाईंले पठाइरहनुभएको यही हो',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'भित्र पस्ने तपाईंको एउटै उपाय यही हो। हटाउनुअघि पासवर्ड राख्नुहोस्।',
  'E-mail': 'इमेल',
