  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.':
    'ठेगाना सुरक्षित भयो। यो सर्भरमा इमेल पठाउने सुविधा अझै खुलेको छैन, त्यसैले पुष्टि लिङ्क सर्भरको लगमा रह्यो।',
  'Enfeites, sons e emojis': 'सजावट, ध्वनि र इमोजी',
  'Enquanto isto aparecer, os números abaixo não existem —': 'यो देखिउन्जेल तलका अङ्कहरू अस्तित्वमा छैनन् —',
