  'Aniversário': 'जन्मदिन',
  'Aniversários': 'जन्मदिनहरू',
  'Canal dos parabéns': 'शुभकामनाको च्यानल',
  'Dia': 'दिन',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'आज {pessoa} को जन्मदिन हो! 🎉 जन्मदिनको शुभकामना!',
  'Mês': 'महिना',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'मिति राख्नेको जन्मदिनमा Syden ले छानिएको च्यानलमा शुभकामना पोस्ट गर्छ। नामको सट्टा {pessoa} प्रयोग गर्नुहोस्।',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'दिन र महिना मात्र, वर्ष कहिल्यै होइन। जन्मदिन जनाउने समुदायहरूले त्यही दिन शुभकामना दिन्छन्। यो ऐच्छिक हो, जुनसुकै बेला मेटाउन सकिन्छ।',
  'Texto dos parabéns': 'शुभकामनाको पाठ',
