  'Mensagens agendadas': 'तालिकाबद्ध सन्देशहरू',
  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'तोकिएको समयमा Syden ले च्यानलमा पाठ पोस्ट गर्छ। हरेक दिन वा हरेक हप्ता दोहोर्याउन सकिन्छ।',
  'Nova mensagem agendada': 'नयाँ तालिकाबद्ध सन्देश',
