  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'कसैले सन्देशको सुरुमा !regras जस्तो आदेश लेख्छ, र Syden ले तपाईंले राखेको पाठले च्यानलमा जवाफ दिन्छ। माग्नेको नामका लागि {pessoa} र समुदायको नामका लागि {comunidade} प्रयोग गर्नुहोस्।',
