  'Silenciar {pessoa} por': '{pessoa} लाई मौनको अवधि',
  'Silenciar por…': 'मौनको अवधि…',
  'Tirar o silêncio': 'मौन हटाउनुहोस्',
  'Você está em silêncio em {comunidade} até {hora}.': '{comunidade} मा तपाईं {hora} सम्म मौनमा हुनुहुन्छ।',
  'Você está em silêncio nesta comunidade até {hora}.': 'यो समुदायमा तपाईं {hora} सम्म मौनमा हुनुहुन्छ।',
  'Você recebeu uma advertência em {comunidade}: {motivo}': '{comunidade} मा तपाईंले चेतावनी पाउनुभयो: {motivo}',
  'Barrar excesso de mensagens (mais de 5 em 10 segundos)': 'धेरै सन्देश रोक्नुहोस् (१० सेकेन्डमा ५ भन्दा बढी)',
