  'Modo lento': 'ढिलो मोड',
  'Modo lento de {canal}': '{canal} को ढिलो मोड',
  'Modo lento: uma mensagem a cada {tempo}.': 'ढिलो मोड: हरेक {tempo} मा एउटा सन्देश।',
  'Palavras proibidas': 'निषेधित शब्दहरू',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'च्यानलमा हरेक व्यक्तिले सन्देशहरूबीच कति पर्खने।',
  'Regras': 'नियमहरू',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'सन्देश देखिनुअघि Syden आफैँले लागू गर्ने नियमहरू। व्यवस्थापकमा लागू हुँदैनन्। रोकिएको सन्देश कारणसहित लेख्नेकहाँ फर्किन्छ, अरू कसैले देख्दैन।',
  'Salvo.': 'सुरक्षित भयो।',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'हरेक पङ्क्तिमा एउटा। पूरा शब्द गनिन्छ, चिह्न वा ठूला अक्षरको फरक बिना: एउटा शब्द निषेध गर्दा त्यसलाई मात्र समेट्ने लामो शब्द रोकिँदैन।',
  '{faltam} pontos para o nível {proximo}.': 'लेभल {proximo} सम्म {faltam} अंक बाँकी।',
  'Adicionar recompensa': 'पुरस्कार थप्नुहोस्',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'हरेक सन्देशमा अंक मिल्छ (मिनेटमा एक), अरू कसैसँग कोठामा बिताएको हरेक मिनेटमा पनि। लेभल बढ्नेलाई मात्र सूचना आउँछ।',
  'Cargo da recompensa': 'पुरस्कारको भूमिका',
  'Crie um cargo acima para usar como recompensa.': 'पुरस्कारका रूपमा प्रयोग गर्न माथि भूमिका बनाउनुहोस्।',
