  'Cargos dão nome e cor a grupos de pessoas: "Veterano", "Turma da raide". Não mudam o que cada um pode fazer na comunidade.': 'भूमिकाले मानिसहरूका समूहलाई नाम र रङ दिन्छ: "पुराना सदस्य", "रेड टोली"। समुदायमा कसले के गर्न सक्छ भन्ने कुरा बदल्दैन।',
