  'Esse nome de usuário já está em uso.': 'यो प्रयोगकर्ता नाम पहिले नै लिइसकिएको छ।',
  'Esta comunidade ainda não tem sala de voz.': 'यो समुदायमा अझै भ्वाइस कोठा छैन।',
