  'Esta música não tem letra. Dá para subir de novo com um arquivo .lrc junto.':
    'यो गीतको शब्द छैन। .lrc फाइलसँगै फेरि अपलोड गर्न सकिन्छ।',
  'Esta pessoa excluiu a conta. As mensagens daqui não chegam a ninguém.':
    'यो व्यक्तिले खाता मेटाइसक्नुभएको छ। यहाँका सन्देश कसैकहाँ पुग्दैनन्।',
