  'O que você fez a respeito?': 'यसबारे तपाईंले के गर्नुभयो?',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.':
    'पहिलो लक्ष्य पूरा भएपछि छाप यहाँ देखिन्छ। त्यतिन्जेल यो सुरक्षित रहन्छ — र त्यहाँ पुग्नु नै यसको अर्थ हुनेछ।',
  'O selo desta comunidade é': 'यो समुदायको छाप:',
  'O servidor demorou demais para responder. Tente de novo.': 'सर्भरले जवाफ दिन धेरै ढिला गर्‍यो। फेरि प्रयास गर्नुहोस्।',
  'O som chega quando você abre esta transmissão.': 'तपाईंले यो स्ट्रिम खोलेपछि आवाज आउँछ।',
  'O survival do Léo': 'सुमनको survival सर्भर',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.':
    'Syden ले यीमध्ये जुनसुकै भाषामा लेख्न जान्दछ — पाठहरूको अनुवाद मात्र बाँकी छ। अनुवाद नआउन्जेल अनूदित नभएका कुरा पोर्चुगिज भाषामा देखिन्छन्, र हरेक लिपिका अक्षर ठीकसँग, बट्टाबिना देखिन्छन्।',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'अपडेटका लागि Syden करिब १० मिनेट बन्द रहनेछ।',
  'Observação': 'टिप्पणी',
