  'Olhe o seu e-mail': 'आफ्नो इमेल हेर्नुहोस्',
  'Opções': 'विकल्पहरू',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.':
    'तलका लक्ष्यहरू एक्लै पुग्न नसकिने गरी छानिएका हुन् — सबैलाई समयसँगै एकभन्दा बढी मान्छे चाहिन्छ।',
  'Os outros idiomas': 'अरू भाषाहरू',
