  'Seu microfone está desligado enquanto você assiste': 'तपाईं हेर्दै गर्दा माइक्रोफोन बन्द छ',
  'Seu microfone não está mandando som: ninguém está te ouvindo. Clique para escolher outro.':
    'तपाईंको माइक्रोफोनले आवाज पठाइरहेको छैन: कसैले तपाईंलाई सुनिरहेको छैन। अर्को छान्न क्लिक गर्नुहोस्।',
  'Seu status': 'तपाईंको स्थिति',
  'Silenciar': 'म्युट गर्नुहोस्',
