  'Site do Syden': 'Syden को साइट',
  'Só as letras mudam: o resto da tela fica no lugar.': 'अक्षर मात्र फेरिन्छन्: स्क्रिनको बाँकी भाग जहाँको त्यहीँ रहन्छ।',
