  'Só quem administra pode instalar ou tirar.': 'प्रशासकहरूले मात्र इन्स्टल गर्न वा हटाउन सक्छन्।',
  'Só quem administra vê este bloco': 'यो खण्ड प्रशासकहरूले मात्र देख्छन्',
  'Só você vê': 'तपाईंले मात्र देख्नुहुन्छ',
