  'Som da transmissão': 'स्ट्रिमको आवाज',
  'Sombra': 'छाया',
  'Some e volta devagar, como respirando.': 'सास फेरेझैँ बिस्तारै हराउँछ र फर्कन्छ।',
  'some em 7 dias': '७ दिनमा हराउँछ',
  'Some sozinho às': 'आफैँ हराउने समय:',
