  'Sua anotação — clique para mudar': 'तपाईंको टिपोट — बदल्न क्लिक गर्नुहोस्',
  'Sua ideia': 'तपाईंको विचार',
  'Sua ideia entrou no Syden!': 'तपाईंको विचार Syden मा थपियो!',
  'Sua ideia foi acolhida': 'तपाईंको विचार स्वीकारियो',
  'Sua internet está segurando a qualidade.': 'तपाईंको इन्टरनेटले गुणस्तर रोकिरहेको छ।',
  'Sua senha, para confirmar que é você': 'तपाईं नै हो भनी पुष्टि गर्न तपाईंको पासवर्ड',
  'Sua transmissão está sem som. O navegador só manda o som se você marcar “compartilhar áudio” na janelinha de escolher a tela.':
    'तपाईंको स्ट्रिममा आवाज छैन। स्क्रिन छान्ने सानो विन्डोमा “अडियो सेयर गर्ने” मा चिन्ह लगाउनुभयो भने मात्र ब्राउजरले आवाज पठाउँछ।',
  'Sua voz': 'तपाईंको आवाज',
  'Suba músicas que você já tem. Um arquivo': 'आफूसँग भएका गीतहरू अपलोड गर्नुहोस्।',
  'Suba só o que é seu ou o que você tem direito de usar. Ter o arquivo não é o mesmo que ter direito de tocar para outras pessoas.':
    'आफ्नो वा प्रयोग गर्ने अधिकार भएको कुरा मात्र अपलोड गर्नुहोस्। फाइल हुनु र अरूलाई बजाएर सुनाउने अधिकार हुनु एउटै कुरा होइन।',
  'Sugestões de melhoria': 'सुधारका सुझावहरू',
  'Supressão de ruído': 'हल्ला दबाउने',
  'Tamanho do texto': 'अक्षरको आकार',
  'Também dá para arrastar a borda de cada barra na tela. Dois cliques na borda volta ao padrão.':
    'स्क्रिनमा हरेक प्यानलको किनारा तान्न पनि सकिन्छ। किनारामा दुई पटक क्लिक गर्दा पूर्वनिर्धारितमा फर्कन्छ।',
  'Também dá para colar o endereço de um GIF ou de uma imagem. O Syden baixa uma cópia e guarda: se o endereço sair do ar depois, a capa continua.':
    'GIF वा तस्बिरको ठेगाना टाँस्न पनि सकिन्छ। Syden ले एउटा प्रति डाउनलोड गरेर राख्छ: पछि ठेगाना बन्द भए पनि कभर रहिरहन्छ।',
  'Também de graça, e também trocáveis quando quiser. Ficam nas configurações da comunidade, porque valem para a comunidade inteira e não só para você.':
    'यी पनि निःशुल्क, र जहिले पनि बदल्न मिल्ने। तपाईंका लागि मात्र नभई पूरै समुदायका लागि लागू हुने भएकाले समुदायका सेटिङमा रहन्छन्।',
  'Teclas de atalho': 'सर्टकट कुञ्जीहरू',
