  'Tirar opção': 'विकल्प हटाउनुहोस्',
  'Título': 'शीर्षक',
  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.':
    'कोही तपाईंको कोठामा आउँदा वा जाँदा, कसैले स्क्रिन सेयर सुरु गर्दा, र तपाईंले माइक वा आवाज बन्द गर्दा ध्वनि बजाउँछ।',
  'Tocando…': 'बज्दै…',
  'Toda letra com a mesma largura.': 'सबै अक्षर उत्रै चौडाइका।',
  'Todas as cores girando devagar. A mais chamativa de todas.': 'सबै रङ बिस्तारै घुम्दै। सबैभन्दा आकर्षक।',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.':
    'यो समुदायका सबैले {exemplo} लेखेर वा च्याटको इमोजी बटनबाट यी इमोजी प्रयोग गर्न सक्छन्। सदस्यता चाहिँदैन: सबै खुला छ।',
  'Tom mais alto e mais claro.': 'अझ अग्लो र प्रस्ट स्वर।',
  'Tom mais baixo e mais encorpado.': 'अझ होचो र भरिलो स्वर।',
  'Tráfego de saída este mês': 'यो महिनाको बाहिर जाने ट्राफिक',
