  'Cargos automáticos': 'स्वचालित भूमिकाहरू',
  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'पहिले सदस्यहरू मा समुदायका भूमिकाहरू बनाउनुहोस्। त्यसपछि ती आफैँ दिइयोस् भनेर यहाँ फर्कनुहोस्।',
  'Cargo de quem entra': 'नयाँ आउनेको भूमिका',
  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'हरेक नयाँ व्यक्तिलाई समुदायमा सामेल हुँदा यी भूमिकाहरू दिइन्छ।',
  'Cargos por reação': 'प्रतिक्रियाबाट भूमिकाहरू',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden ले च्यानलमा हरेक भूमिकाका लागि एउटा इमोजीसहित सन्देश राख्छ। प्रतिक्रिया दिनेलाई भूमिका दिइन्छ; प्रतिक्रिया हटाउनेबाट भूमिका हटाइन्छ।',
  'Apagar o painel': 'प्यानल मेटाउनुहोस्',
  'Escolha os seus cargos reagindo aqui embaixo!': 'तल प्रतिक्रिया दिएर आफ्ना भूमिकाहरू छान्नुहोस्!',
