  'Mais um emoji': 'अर्को इमोजी',
  'Publicar o painel': 'प्यानल प्रकाशित गर्नुहोस्',
  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': 'समूहले कुन खेलहरू, कति जनासँग खेल्छ र कति खेल अन्त्यसम्म पुग्छन्। गन्ती मात्र: उत्तर र चित्रहरू राखिँदैनन्। 12/10/2026 देखि गनिएको।',
