  'A música': 'गीत',
  'O emoji': 'इमोजी',
  'O arquivo': 'फाइल',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) Syden बाट हटाइएको छ, किनभने {quem} ले यसको अधिकार आफूसँग भएको दाबी गर्नुभएको छ। यदि तपाईंसँग प्रकाशित गर्ने अनुमति थियो भने, यहाँ जवाफ दिएर बताउनुहोस्: तपाईंको जवाफलाई ध्यानमा राखिनेछ। यो स्पष्ट नहुँदासम्म यो हटाइएकै रहन्छ। यो कसरी काम गर्छ भन्ने कुरा सर्तहरूको खण्ड 4 मा छ: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}» हटाइयो।',
  'Saíram junto {n} cópia(s) do mesmo arquivo.': 'सँगै हटाइएका सोही फाइलका प्रतिलिपिहरू: {n}',
  'Quem subiu recebeu o aviso numa conversa com você.': 'अपलोड गर्ने व्यक्तिलाई तपाईंसँगको कुराकानीमा सूचना पठाइयो।',
  'Não havia a quem avisar.': 'सूचना दिनुपर्ने कोही थिएन।',
  'É a retirada número {n} desta pessoa.': 'यस व्यक्तिको सामग्री हटाइएको यो {n} औँ पटक हो।',
  'Direito autoral': 'प्रतिलिपि अधिकार',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'अधिकार भएको व्यक्तिले direitos@syden.chat मा के हो र कहाँ छ भनेर लेख्नुहुन्छ। नामबाट खोज्नुहोस्, हटाउनुहोस्, र अपलोड गर्ने व्यक्तिलाई तपाईंसँगको कुराकानीमा सूचना जान्छ, जहाँ आपत्ति जनाउन सकिन्छ।',
