  'Tickets': 'टिकटहरू',
  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'प्रशासनसँग कुरा गर्नुपर्ने व्यक्तिले समुदायको सुरु पृष्ठबाट विषयसहित टिकट खोल्नुहुन्छ। यो त्यो व्यक्ति र प्रशासकहरूबीचको निजी समूह कुराकानी बन्छ, र तपाईंहरूको कुराकानी सूचीमा देखिन्छ।',
