  'Obrigado de verdade. Fique de olho nas novidades da tela inicial para ver a sua ideia funcionando — e a medalha de contribuição já está no seu perfil.': 'साँच्चै धन्यवाद। गृह स्क्रिनका नयाँ कुरामा नजर राख्नुहोस्, तपाईंको सुझाव काम गरेको देख्नुहुनेछ — र योगदानको पदक तपाईंको प्रोफाइलमा पहिले नै छ।',
