  'Não chegou em alguns minutos? Dê uma olhada no spam ou nas promoções. Se não estiver lá, mande de novo.': 'केही मिनेटमा आएन? स्प्याम वा प्रमोसनमा हेर्नुहोस्। त्यहाँ पनि छैन भने फेरि पठाउनुहोस्।',
