  '{n} emojis entraram. Ficaram de fora, porque a comunidade já tem esses nomes: {nomes}': '{n} इमोजी थपिए। यी बाहिर रहे, किनभने समुदायमा यी नाम पहिले नै छन्: {nomes}',
