  'O Syden é para quem tem 13 anos ou mais.': 'Syden १३ वर्ष वा सोभन्दा माथिकाका लागि हो।',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Syden १३ वर्ष वा सोभन्दा माथिकाका लागि हो। तपाईंको मिति कसैले देख्दैन।',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'Syden ले अब सबैको उमेर सोध्छ, १८ वर्षमुनिकाहरूको सुरक्षाका लागि (ECA Digital कानुन)। तपाईंको मिति कसैले देख्दैन: उमेर समूह मात्र प्रयोग हुन्छ।',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'कसलाई जानकारी दिइयो र प्रोटोकल (जस्तै: SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'सुरक्षाका लागि, नाबालकहरूका लागि स्ट्रिमको पूर्वावलोकन बन्द रहन्छ।',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'सुरक्षाका लागि, नाबालकहरूको निजी कुराकानी साथीहरूसँग मात्र हुन्छ।',
  'Qual é a sua data de nascimento?': 'तपाईंको जन्म मिति कति हो?',
