  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': '१३ देखि १५ वर्षकाहरूले बुबा, आमा वा अभिभावकको खातासँग जोडिएको खाताबाट Syden चलाउँछन्। यो कानुन (ECA Digital) हो, र तपाईंको सुरक्षाका लागि हो।',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': '१८ वर्षमुनिकाहरूले थप सुरक्षासहित Syden चलाउँछन्, र १३ देखि १५ वर्षकाहरूको खाता अभिभावकको खातासँग जोडिन्छ (ECA Digital कानुन)।',
