  'Horta': 'तरकारी बारी',
  'Setas para dirigir, Espaço para derrapar e carregar o turbo.': 'घुमाउन तीर कुञ्जीहरू, ड्रिफ्ट गर्न र टर्बो चार्ज गर्न स्पेस।',
  'Seu recorde: {tempo}': 'तिम्रो रेकर्ड: {tempo}',
  'Correr contra': 'यिनीहरूसँग दौड',
  'Nenhum amigo correu nesta pista ainda.': 'यो ट्र्याकमा अहिलेसम्म कुनै साथी दौडिएको छैन।',
  'Novo recorde!': 'नयाँ रेकर्ड!',
  'Virar para a esquerda': 'बायाँ मोड',
  'Virar para a direita': 'दायाँ मोड',
  'Derrapar': 'ड्रिफ्ट',
  'Uma corrida de kart. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, com itens e a Copa da Cenoura.': 'कार्ट दौड। एक्लै, घडी र साथीहरूका भूतहरूविरुद्ध; टोलीसँग, प्रत्यक्ष, सामानहरू र गाजर कपसहित।',
  'Pomar': 'फलफूल बगैंचा',
  'Copa da Cenoura': 'गाजर कप',
  'contra {nomes}': '{nomes} विरुद्ध',
  'Usar o item': 'सामान प्रयोग गर',
  'Olhar para trás': 'पछाडि हेर',
  'Setas para dirigir, Espaço para derrapar, E para usar o item.': 'घुमाउन तीर कुञ्जीहरू, ड्रिफ्ट गर्न स्पेस, सामान प्रयोग गर्न E।',
  'Copa da turma': 'टोलीको कप',
  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'खरायो दौडमा टोलीले अन्त्यसम्म दौडेका गाजर कपहरू।',
  'Bosque': 'जङ्गल',
  'Cânion': 'खोंच',
  'Copa do Repolho': 'बन्दा कप',
  'Festa dos coelhos': 'खरायो पार्टी',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'छिटो खेलका पाँच चरण, सबै आ-आफ्नै स्क्रिनमा: प्रतिक्रिया, निशाना, स्मरण र नजर। हरेक चरणमा जो उत्कृष्ट हुन्छ उसले बढी अंक पाउँछ।',
  'Saque rápido': 'छिटो गोली',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'सङ्केत पर्ख र सकेसम्म छिटो थिच। सङ्केतअघि थिचे बाहिर।',
  'Medidor de força': 'बल मिटर',
  'Pare a barra o mais perto possível de 100%.': 'पट्टीलाई सकेसम्म 100% नजिक रोक।',
  'Parar o relógio': 'घडी रोक',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'घडीलाई ठीक 10 सेकेन्डमा रोक। 3 पछि अङ्कहरू हराउँछन्।',
  'Jogo dos copos': 'कपको खेल',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'गाजर कहाँ छ हेर र कपलाई पछ्याऊ। छिटो मिलाए बढी अंक।',
  'Siga o coelho': 'खरायोलाई पछ्याऊ',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'तीरहरू क्रमैसँग दोहोर्‍याऊ। हरेक सहीपछि अर्को एउटा थपिन्छ।',
  'Tiro ao alvo': 'निशानेबाजी',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'देखा पर्ने निशानाहरूमा हान। हरेकको एक अंक।',
  'Cedo demais!': 'धेरै चाँडो!',
  'Não valeu': 'गनिएन',
  'Sem resposta': 'उत्तर छैन',
  'Errou': 'गलत',
  'Nenhum troféu ainda. Fique no pódio de um jogo na sala, com a turma.': 'अहिलेसम्म कुनै ट्रफी छैन। कोठामा टोलीसँगको खेलमा पोडियममा पुग।',
  'Briga na horta': 'बारीमा झगडा',
  'Horta em cascata': 'बारीको झरना',
