  'Silo': 'साइलो',
  'Solte o cipó quando ele estiver na faixa clara.': 'लहरा हल्का पट्टीमा हुँदा छोड।',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'सलगम मैदानतिर फर्किँदा छोड। जति छिटो घुमाए, त्यति टाढा जान्छ।',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'हावा-सूचकसम्म चढ। खस्ने सामान र कागले अन्तिम पुगेको तलामा फर्काउँछन्।',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'हल्लिने फल्याक, परालका मुठा र दलिनहरू हुँदै भकारी घर चढेर टुप्पोको हावा-सूचकसम्म पुग, खस्ने औजार र कागबाट बच्दै। एक्लै खेल्दा घडी र साथीहरूका भूतसँग।',
