  '{n} voltas': '{n} ल्याप',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'ऊर्जा नै जीवन र टर्बो हो: किनारामा ठोक्किँदा खर्च हुन्छ, गुलाबी पट्टीले फेरि भर्छ।',
  'A nave explodiu: a energia acabou.': 'यान विस्फोट भयो: ऊर्जा सकियो।',
  'Posição: {posicao} de {total}': 'स्थान: {total} मध्ये {posicao}',
  'Escolher a pista': 'ट्र्याक छान',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'झुन्डिएको ट्र्याकमा गाजर-यानहरूको दौड, कार्टभन्दा धेरै छिटो। ऊर्जा नै जीवन र टर्बो हो: किनारामा ठोक्किँदा खर्च हुन्छ, गुलाबी पट्टीले फेरि भर्छ, र ट्र्याकबाट बाहिर जानु भनेको खस्नु हो। एक्लै खेल्दा घडी र साथीहरूका भूतसँग।',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'बन्द मैदानमा कार्टहरू, हरेकमा तीनवटा बेलुन। बाकसहरू टिप र सामानले अरूका बेलुन फुटाऊ: जसको बेलुन सकिन्छ, ऊ बाहिर, र जो अन्तिमसम्म टिक्छ, उसको जित।',
  'Esquadrilha da toca': 'दुलोको स्क्वाड्रन',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'गाजरका साना विमानहरू बगैँचाका कीराविरुद्ध: बीउबाट बच, सहयोग टिप र अन्त्यमा यान्त्रिक बुख्याचा खसाल। टोली उही छालहरूमा उड्छ, र स्क्वाड्रनका अङ्क जोडिन्छन्।',
  'O espantalho caiu!': 'बुख्याचा खस्यो!',
  'A praga venceu desta vez.': 'यस पटक कीराहरूले जिते।',
