  'Os navios não podem encostar um no outro.': 'जहाजहरू एकअर्कालाई छुन सक्दैनन्।',
  'Minigolfe 3D': 'मिनीगल्फ 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': '3D मा आठ प्वाल, र्‍याम्प, किल्ला र पवनचक्कीसहित, सबैले एकै समयमा एउटै प्वाल खेल्छन्। निसाना लगाउन र बल दिन तान, अनि छोड। कुलमा सबैभन्दा कम प्रहार गर्ने जित्छ।',
  'Ver o buraco de cima': 'प्वाललाई माथिबाट हेर',
  'Fora da pista! Mais uma tacada.': 'बाटोबाहिर! अर्को एक प्रहार।',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'निसाना लगाउन छेउतिर र बलका लागि तलतिर तान, अनि छोड। किबोर्डमा: तीरहरूले निसाना लगाउँछन्, र थिचिराखेको स्पेसले बल दिन्छ।',
  'Futebol dos coelhos': 'खरायोहरूको फुटबल',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'सानो मैदानको फुटबल, माथिबाट। बल लैजान त्यसलाई छोऊ, बलियो सट हान्न स्पेस थिचिराख, र X ले पास देऊ। कोठामा टोलीहरू रोबोटले पूरा गरिन्छन्।',
  'Quantos por time?': 'प्रति टोली कति जना?',
