  'Caça às pragas da horta': 'बगैँचाका कीराको सिकार',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'काग र सलहले बगैँचामा आक्रमण गरिरहेका छन्। भाग्नुअघि निशाना लगाएर क्लिक गर्नुहोस्: गोली गनिएको छ, र हरेक लहर अझ छिटो आउँछ। सबैभन्दा धेरै अङ्क ल्याउने जित्छ।',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'कीराहरू भाग्नुअघि निशाना लगाएर क्लिक गर्नुहोस्। हरेक गोलीमा एउटा गाजर खर्च हुन्छ।',
