  'Tacadas: {n}': 'प्रहार: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'बललाई पछाडि तानेर छोड। किबोर्डमा: तीरहरूले निसाना लगाउँछन्, र थिचिराखेको स्पेसले बल दिन्छ।',
