  'Para a esquerda': 'बायाँतिर',
  'Para a direita': 'दायाँतिर',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'दौडिन तीर कुञ्जीहरू, उफ्रिन स्पेस (अझ माथि जान थिचिराख)।',
  'Nenhum amigo jogou esta fase ainda.': 'कुनै साथीले अझै यो चरण खेलेको छैन।',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'बारीमा पानी: सबैले {n} गाजर पाउँछन्।',
  '{nome} achou {n} cenouras escondidas.': '{nome} ले {n} लुकेका गाजर भेट्टाउनुभयो।',
  '{nome} trocou de lugar com {outro}.': '{nome} ले {outro} सँग ठाउँ साट्नुभयो।',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'मान्छे पुगेनन्: खेल अन्त्यअघि नै सकियो, ट्रफी बिना।',
  'Saiu antes do fim': 'अन्त्यअघि बाहिरिएको',
  'Jogar o dado': 'पासा फाल',
  '{nome} comprou a cenoura dourada!': '{nome} ले सुनौलो गाजर किन्नुभयो!',
  'Comprar a cenoura dourada por {preco} cenouras?': '{preco} गाजरमा सुनौलो गाजर किन्ने?',
  'Comprar': 'किन',
  '{nome} chegou à cenoura dourada.': '{nome} सुनौलो गाजरसम्म पुग्नुभयो।',
  'Quantas rodadas?': 'कति चरण?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'खरायोहरूले बारीलाई स्याल, काग र एउटा बिज्जुबाट जोगाउँछन्। सँगै हिँड, कम्बोमा हान र एकअर्काको ख्याल गर: १ देखि ४ जनासम्म।',
  'Pulo do coelho': 'खरायोको उफ्राइ',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'प्लेटफर्म दौड: दौड, उफ्र र नखस। एक्लै, घडी र साथीहरूका भूतहरूविरुद्ध; टोलीसँग, प्रत्यक्ष, एउटा चरणमा वा तीनैमा।',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'छेउछाउका दुई तरकारी साटेर तीन वा बढी उस्तै जम्मा गर। थुप्रो नरोकी माथि चढ्छ: माथिसम्म पुग्न नदेऊ। टोलीसँग, शृङ्खला र कम्बोले अरूलाई बाकसहरू पठाउँछन्।',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'मिनीगल्फका छवटा दुला, सबैले एकै समयमा एउटै खेल्छन्। प्रहार गर्न बललाई पछाडि तानेर छोड। जम्मा सबैभन्दा कम प्रहार गर्ने जित्छ।',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'सबैले आफ्नो पालोमा पासा फाल्छन् र बारीभरि हिँड्छन्। सुनौलो गाजर किन्न गाजर जम्मा गर, र हरेक चरणपछि टोलीले एउटा सानो खेल खेल्छ। सबैभन्दा धेरै सुनौलो गाजर हुने जित्छ।',
  'Os pódios e as conquistas da turma': 'पोडियम र टोलीका उपलब्धिहरू',
  'Visitar o quarto': 'कोठा हेर्न जानुहोस्',
  'Quem visita o seu quarto': 'तपाईंको कोठामा को आउन सक्छ',
  'Todo mundo': 'सबै जना',
  'Seus amigos': 'तपाईंका साथीहरू',
  'Só quem você convidar': 'तपाईंले बोलाएका मात्र',
  'Qualquer conta pode entrar e ver os troféus em destaque.': 'जुनसुकै खाताले भित्र आएर विशेष ट्रफीहरू हेर्न सक्छ।',
  'Seus amigos podem entrar e ver os troféus em destaque.': 'तपाईंका साथीहरूले भित्र आएर विशेष ट्रफीहरू हेर्न सक्छन्।',
  'Nem os amigos entram, só quem você marcar aqui.': 'साथीहरू पनि आउन पाउँदैनन्, यहाँ तपाईंले छानेकाहरू मात्र।',
  'Você ainda não tem amigos para convidar.': 'तपाईंसँग बोलाउने साथी अझै छैनन्।',
  'Tirar do destaque': 'विशेषबाट हटाउनुहोस्',
  'Pôr em destaque': 'विशेषमा राख्नुहोस्',
  'Cabem até {n} em destaque': '{n} वटासम्म विशेषमा राख्न सकिन्छ',
  'Troféus de {nome}': '{nome} का ट्रफीहरू',
  'Em destaque': 'विशेष',
  'Nada em destaque ainda.': 'अझै केही विशेषमा छैन।',
  'Escolha pela estrela o que fica em destaque. É o que quem visita o seu quarto vê.': 'ताराबाट विशेषमा राख्ने कुरा छान्नुहोस्। तपाईंको कोठामा आउनेहरूले यही देख्छन्।',
  'Conquistas da turma: {comunidade}': 'टोलीका उपलब्धिहरू: {comunidade}',
