  '{quem} chama você para visitar o quarto': '{quem} ले तपाईंलाई कोठा हेर्न बोलाउँदै हुनुहुन्छ',
  'Convite para o quarto': 'कोठाको निम्तो',
  'Corrida inválida.': 'अमान्य दौड।',
  'Muitas corridas seguidas. Tente de novo daqui a pouco.': 'लगातार धेरै दौडहरू। केही बेरपछि फेरि प्रयास गर।',
  'A corrida não está andando.': 'दौड चलिरहेको छैन।',
