  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'ब्राजिलका राजधानीहरूमा घुम्नुहोस्, सहर किन्नुहोस् र त्यहाँ रोकिनेहरूबाट भाडा उठाउनुहोस्। पूरै क्षेत्र भए भवन बनाउन सकिन्छ। साटासाट गर्नुहोस्, लिलामीमा होड गर्नुहोस् र पैसा सकिन नदिनुहोस्।',
