  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'उही पुरानो डोमिनो, २ देखि ४ जनासम्म (४ जना भए जोडीमा)। गोटीहरू छेउबाट मिलाउनुहोस्, र जसले पहिले सक्छ उसले अरूको हातका अंक लैजान्छ।',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'साओ पाउलोको ट्रुको, भिरा र मानिलासहित, २ जनामा वा ४ जनाको जोडीमा। ट्रुको माग्नुहोस्, छ, नौ र बाह्रसम्म बढाउनुहोस्, वा भाग्नुहोस्। जसले १२ अंक बनाउँछ, उही जित्छ।',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'ब्राजिली चेकर्स: काट्नु अनिवार्य छ, अगाडि र पछाडि दुवैतिर, र राजा पूरै विकर्ण हिँड्छ। कोठाले हेर्छ।',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'हरेकले आफ्नो बेडा लुकाउँछ र अर्काको समुद्रमा गोला हान्छ। लाग्यो भने फेरि हान्नुहोस्। जसले पहिले पूरै बेडा डुबाउँछ, उही जित्छ। कोठाले हेर्छ।',
