  "{nome} saiu da sala.": "{nome} ले कोठा छोड्नुभयो।",
  "{nome} sentiu o veneno.": "{nome} लाई विषले छोयो।",
  "{nome} tem a palavra. Ouçam a defesa.": "बोल्ने पालो {nome} को हो। बचाउ सुन्नुहोस्।",
  "{nome} terminou uma Maravilha: derrube-a em 2 minutos!": "{nome} ले एउटा आश्चर्य पूरा गर्नुभयो: 2 मिनेटभित्र ढाल्नुहोस्!",
