  "{nome} vai escolher quem enfrentar.": "कोसँग भिड्ने, {nome} ले छान्नुहुनेछ।",
  "{nome}: {tiros} tiros, {pct}% de acerto": "{nome}: {tiros} गोली, {pct}% निसानामा",
  "1 contra 3": "1 विरुद्ध 3",
  "2 contra 2": "2 विरुद्ध 2",
  "A armadilha de {nome} disparou: quem sai junto?": "{nome} को पासो चल्यो: सँगै को बाहिरिन्छ?",
  "A largada precisa de uma reta.": "सुरुका लागि सिधा भाग चाहिन्छ।",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "{nome} को आश्चर्य 2 मिनेटसम्म उभिइरह्यो।",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "एउटै स्थिति तेस्रो पटक आए बराबरी, र केही नखाई राजाका मात्र 20 चाल पनि।",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "रातमा हेर्नुहोस् ब्वाँसो-मानवहरूले कसलाई आक्रमण गरे। एउटा औषधिले त्यो व्यक्तिलाई बचाउँछ र अर्कोले कसैलाई खेलबाट निकाल्छ; हरेक एक पटक मात्र।",
  "A partida se desencontrou entre os computadores e foi encerrada.": "कम्प्युटरहरूबीच खेलको तालमेल बिग्रियो र खेल बन्द गरियो।",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "चाल अन्तिम पङ्क्तिमा सक्ने गोटी राजा बन्छ, जुन पूरै छड्के हिँड्छ।",
  "A pista ainda não fecha a volta.": "ट्र्याकले अझै पूरा फन्को बनाउँदैन।",
  "A pista está curta demais.": "ट्र्याक धेरै छोटो छ।",
  "A pista passa por cima dela mesma.": "ट्र्याक आफैमाथिबाट जान्छ।",
  "A pista precisa de mais peças.": "ट्र्याकलाई अझ टुक्रा चाहिन्छ।",
  "A turma age antes nas duas rodadas seguintes.": "अर्को दुई राउन्डमा टोली पहिले चल्छ।",
  "A turma está decidindo.": "टोली निर्णय गर्दैछ।",
  "A turma inteira leva bem menos dano nesta rodada.": "यस राउन्डमा पूरै टोलीलाई धेरै कम क्षति हुन्छ।",
