  "No tabuleiro de 10 × 10, as internacionais, são 20 pedras de cada lado; a regra é a mesma.": "10 × 10 बोर्डमा, अर्थात् अन्तर्राष्ट्रिय चेकर्समा, हरेक पक्षमा 20 गोटी हुन्छन्; नियम उही हो।",
