  "Qual é o filhote da vaca?": "गाईको बच्चालाई के भनिन्छ?",
  "Qual é o filhote do cavalo?": "घोडाको बच्चालाई के भनिन्छ?",
  "Qual é o ingrediente principal do pão?": "पाउरोटीको मुख्य सामग्री के हो?",
  "Qual é o maior animal do mundo?": "विश्वको सबैभन्दा ठुलो जनावर कुन हो?",
  "Qual é o maior deserto quente do mundo?": "विश्वको सबैभन्दा ठुलो तातो मरुभूमि कुन हो?",
  "Qual é o maior país do mundo em área?": "क्षेत्रफलमा विश्वको सबैभन्दा ठुलो देश कुन हो?",
  "Qual é o maior planeta do Sistema Solar?": "सौर्यमण्डलको सबैभन्दा ठुलो ग्रह कुन हो?",
