  "Qual planeta fica mais perto do Sol?": "कुन ग्रह सूर्यको सबैभन्दा नजिक छ?",
  "Qual sólido tem seis faces quadradas?": "कुन ठोस आकृतिका छवटा वर्गाकार सतह हुन्छन्?",
  "Quantas asas tem uma borboleta?": "पुतलीका कतिवटा पखेटा हुन्छन्?",
  "Quantas cores tem o arco-íris, na conta mais comum?": "सामान्य गणनामा इन्द्रेणीमा कतिवटा रङ हुन्छन्?",
  "Quantas horas tem um dia?": "एक दिनमा कति घण्टा हुन्छन्?",
  "Quanto é dez menos três?": "दस घटाउ तीन कति हुन्छ?",
  "Quanto é metade de dez?": "दसको आधा कति हो?",
  "Quanto é o dobro de seis?": "छको दोब्बर कति हो?",
  "Quanto é sete vezes oito?": "सात गुणा आठ कति हुन्छ?",
  "Quanto é três mais quatro?": "तीन जोड चार कति हुन्छ?",
  "Quanto tempo a Terra leva para dar uma volta em torno do Sol?": "पृथ्वीलाई सूर्यको एक फन्को लगाउन कति समय लाग्छ?",
  "Quanto tempo a Terra leva para girar em torno de si mesma?": "पृथ्वीलाई आफ्नै अक्षमा एक फन्को घुम्न कति समय लाग्छ?",
  "Quantos anos tem um século?": "एक शताब्दीमा कति वर्ष हुन्छन्?",
  "Quantos anos tem uma década?": "एक दशकमा कति वर्ष हुन्छन्?",
