  "Quantos dentes tem um adulto, normalmente?": "वयस्कका सामान्यतया कतिवटा दाँत हुन्छन्?",
  "Quantos dias tem um ano que não é bissexto?": "लिप वर्ष नभएको वर्षमा कति दिन हुन्छन्?",
  "Quantos dias tem uma semana?": "एक हप्तामा कति दिन हुन्छन्?",
