  "Quatorze": "चौध",
  "Que animal carrega a casa nas costas?": "कुन जनावरले आफ्नो घर ढाडमा बोकेर हिँड्छ?",
  "Que animal tem listras pretas e brancas?": "कुन जनावरको शरीरमा कालो र सेतो धर्सा हुन्छन्?",
