  "Que bicho produz mel?": "कुन जीवले मह बनाउँछ?",
  "Que fruta é a base do guacamole?": "ग्वाकामोलेको मूल फल कुन हो?",
  "Que fruta é amarela e comprida?": "कुन फल पहेँलो र लामो हुन्छ?",
