  "Rei e dama contra rei": "राजा र वजिर विरुद्ध राजा",
  "Rei e peão contra rei": "राजा र प्यादा विरुद्ध राजा",
  "Rei e torre contra rei": "राजा र हात्ती विरुद्ध राजा",
