  "Roma": "रोम",
  "Roxa": "बैजनी",
  "Rússia": "रुस",
  "Saara": "सहारा",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "एउटा गोप्य जनावर छानिन्छ, र सबैले अनुमान लगाउँछन्। हरेक अनुमानले गोप्यसँग के मिल्छ देखाउँछ: वर्ग, आहार, बस्ने ठाउँ र तौल। कम अनुमानमा मिलाउनेले बढी अङ्क पाउँछ।",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "एउटा गोप्य डाइनोसर छानिन्छ, र सबैले अनुमान लगाउँछन्। हरेक अनुमानले गोप्यसँग के मिल्छ देखाउँछ: काल, आहार, समूह, लम्बाइ र भेटिएको ठाउँ। कम अनुमानमा मिलाउनेले बढी अङ्क पाउँछ।",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "एउटा गोप्य रासायनिक तत्व छानिन्छ, र सबैले अनुमान लगाउँछन्। हरेक अनुमानले गोप्यसँग के मिल्छ देखाउँछ: परिवार, भौतिक अवस्था, आवर्त, समूह र परमाणु सङ्ख्या। कम अनुमानमा मिलाउनेले बढी अङ्क पाउँछ।",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "ब्राजिलको एउटा गोप्य राज्य छानिन्छ, र सबैले अनुमान लगाउँछन्। हरेक अनुमानले गोप्यसम्मको दूरी र दिशा, क्षेत्र, जनसङ्ख्या, क्षेत्रफल, समुद्री तट र अर्को देशसँगको सीमा देखाउँछ। कम अनुमानमा मिलाउनेले बढी अङ्क पाउँछ।",
