  "Você aguenta o primeiro ataque dos lobisomens. Ninguém fica sabendo.": "ब्वाँसो-मानवहरूको पहिलो आक्रमणले तिमीलाई केही गर्दैन। कसैलाई थाहा हुँदैन।",
  "Você colheu {n} recursos.": "{n} स्रोत जम्मा भए।",
  "Você joga por conta própria: vence se a vila tirar você do jogo no julgamento. Levante suspeitas, mas sem exagero.": "यो भूमिका आफ्नै लागि खेलिन्छ: सुनुवाइमा गाउँले तिमीलाई खेलबाट निकाले तिम्रो जित। शङ्का जगाऊ, तर धेरै नबढाई।",
