  "Tirar o status": "स्थिति हटाउनुहोस्",
  "Neste canal de avisos, só quem administra escreve. Dá para responder num tópico.": "यो सूचना च्यानलमा प्रशासकहरूले मात्र लेख्छन्। थ्रेडमा जवाफ दिन सकिन्छ।",
  "Só canal de texto vira canal de avisos.": "पाठ च्यानल मात्र सूचना च्यानल बन्न सक्छ।",
  "Só quem escreveu a mensagem pode editá-la.": "सन्देश लेख्ने व्यक्तिले मात्र यसलाई सम्पादन गर्न सक्छ।",
  "Esta mensagem não tem texto para editar.": "यो सन्देशमा सम्पादन गर्ने पाठ छैन।",
