  "Este convite já foi usado o máximo de vezes.": "यो निम्तो बढीमा जति पटक प्रयोग गर्न मिल्छ, त्यति पटक प्रयोग भइसक्यो।",
  "Escolha uma validade e um limite de usos da lista.": "सूचीबाट म्याद र प्रयोगको सीमा रोज्नुहोस्।",
  "Você já tem convites demais nesta comunidade. Revogue algum antes de criar outro.": "यो समुदायमा तपाईंका निम्ता धेरै भइसके। अर्को बनाउनुअघि कुनै एउटा रद्द गर्नुहोस्।",
  "Convite não encontrado.": "निम्तो भेटिएन।",
  "Só quem criou o convite, ou quem administra a comunidade, pode revogá-lo.": "निम्तो बनाउने व्यक्ति वा समुदायका प्रशासकहरूले मात्र यसलाई रद्द गर्न सक्छन्।",
  "Só quem administra a comunidade vê o registro de moderação.": "मोडरेसन लग समुदायका प्रशासकहरूले मात्र देख्छन्।",
  "Só quem está na sala muda o status dela.": "कोठामा भएकाहरूले मात्र यसको स्थिति बदल्न सक्छन्।",
  "O status da sala tem no máximo 60 caracteres.": "कोठाको स्थितिमा बढीमा ६० अक्षर हुन्छ।",
  "A sala está vazia: o status só aparece com alguém nela.": "कोठा खाली छ: कोही भएपछि मात्र स्थिति देखिन्छ।",
  "Esta comunidade não permite uma das palavras deste status.": "यो समुदायले यो स्थितिको एउटा शब्दलाई अनुमति दिँदैन।",
  "Esta comunidade não permite links no status da sala.": "यो समुदायले कोठाको स्थितिमा लिङ्कलाई अनुमति दिँदैन।",
  "Espere alguns segundos para mudar o status da sala de novo.": "कोठाको स्थिति फेरि बदल्नुअघि केही सेकेन्ड पर्खनुहोस्।",
